"""Embed the local Python source so index.html also works from file://."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent
source = root.joinpath("deck_rotation.py").read_text(encoding="utf-8")
root.joinpath("python-source.js").write_text(
    "// Generated by build.py from the local deck_rotation.py. Do not edit.\n"
    + "window.DECK_ROTATION_SOURCE = " + json.dumps(source) + ";\n",
    encoding="utf-8",
)
